template <typename T>
struct HasBegin {
private:
    template <typename C> static std::true_type test(decltype(std::declval<C>().begin())*);
    template <typename C> static std::false_type test(...);
public:
    static constexpr bool value = decltype(test<T>(nullptr))::value;
};

struct Container { void begin() {} };
constexpr bool check = HasBegin<Container>::value; // true

